//! `hydra language-server`: the Language Server Protocol over stdin/stdout.
//!
//! Completion, hover and signature help for the builtins and the standard
//! modules come from the interpreter's own table ([`Native::info`]) for the
//! signatures and from `editor/reference.json` for the descriptions. That
//! file is generated by `docs/build.py` from the reference copy, so an editor
//! never describes a function differently from the published reference.
//! Diagnostics are `hydra check`'s and formatting is `hydra fmt`'s.
//!
//! The context of a completion is read from the text before the cursor rather
//! than from the tree: the line being typed is usually the one that does not
//! parse. Declarations come from the last version of the document that did.

use std::collections::{HashMap, HashSet};
use std::io::{self, BufRead, Write};
use std::path::{Path, PathBuf};
use std::sync::LazyLock;

use serde_json::{json, Value};

use crate::ast::{ClosureBody, Expr, Program, Stmt};
use crate::check::{check_program, CheckOptions};
use crate::errors::{Pos, Severity};
use crate::format::format_source;
use crate::lexer::{is_ident_char, is_ident_start, is_private, COMPOUND, KEYWORDS};
use crate::parser::parse;
use crate::value::{BUILTIN_MODULES, NATIVES};

static REFERENCE: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(include_str!("../editor/reference.json")).expect("editor/reference.json is JSON")
});

/// Serve one client until it sends `exit` or closes stdin.
pub fn serve() -> io::Result<i32> {
    let stdin = io::stdin();
    let mut input = stdin.lock();
    let stdout = io::stdout();
    let mut server = Server::default();
    while let Some(message) = read_message(&mut input)? {
        for reply in server.handle(message) {
            let mut out = stdout.lock();
            write_message(&mut out, &reply)?;
        }
        if let Some(code) = server.exit {
            return Ok(code);
        }
    }
    Ok(if server.shutdown { 0 } else { 1 })
}

fn read_message(input: &mut impl BufRead) -> io::Result<Option<Value>> {
    let mut length = None;
    loop {
        let mut line = String::new();
        if input.read_line(&mut line)? == 0 {
            return Ok(None);
        }
        let line = line.trim_end();
        if line.is_empty() {
            break;
        }
        if let Some((key, value)) = line.split_once(':') {
            if key.eq_ignore_ascii_case("content-length") {
                length = value.trim().parse::<usize>().ok();
            }
        }
    }
    let Some(length) = length else {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "message without Content-Length"));
    };
    let mut body = vec![0; length];
    input.read_exact(&mut body)?;
    serde_json::from_slice(&body).map(Some).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))
}

fn write_message(out: &mut impl Write, message: &Value) -> io::Result<()> {
    let body = message.to_string();
    write!(out, "Content-Length: {}\r\n\r\n{body}", body.len())?;
    out.flush()
}

/// The unit a client counts columns in. Hydra's own positions count
/// characters, which is UTF-32.
#[derive(Clone, Copy, Default, PartialEq)]
enum Encoding {
    Utf8,
    #[default]
    Utf16,
    Utf32,
}

impl Encoding {
    fn width(self, c: char) -> usize {
        match self {
            Encoding::Utf8 => c.len_utf8(),
            Encoding::Utf16 => c.len_utf16(),
            Encoding::Utf32 => 1,
        }
    }

    /// Client units to a character index into `line`.
    fn to_chars(self, line: &str, units: usize) -> usize {
        let mut seen = 0;
        for (i, c) in line.chars().enumerate() {
            if seen >= units {
                return i;
            }
            seen += self.width(c);
        }
        line.chars().count()
    }

    /// A character index into `line` to client units.
    fn to_units(self, line: &str, chars: usize) -> usize {
        line.chars().take(chars).map(|c| self.width(c)).sum()
    }
}

struct Document {
    text: String,
    /// The last version that parsed, for declarations while the current one
    /// does not.
    program: Option<Program>,
    file: String,
}

impl Document {
    fn line(&self, index: usize) -> &str {
        let line = self.text.split('\n').nth(index).unwrap_or("");
        line.strip_suffix('\r').unwrap_or(line)
    }

    fn dir(&self) -> PathBuf {
        Path::new(&self.file).parent().map(Path::to_path_buf).filter(|p| !p.as_os_str().is_empty()).unwrap_or_else(|| PathBuf::from("."))
    }
}

#[derive(Default)]
pub struct Server {
    documents: HashMap<String, Document>,
    encoding: Encoding,
    shutdown: bool,
    exit: Option<i32>,
}

impl Server {
    pub fn new() -> Server {
        Server::default()
    }

    /// Answer one message: a response for a request, and any notifications
    /// it causes (diagnostics).
    pub fn handle(&mut self, message: Value) -> Vec<Value> {
        let method = message["method"].as_str().unwrap_or("").to_string();
        let params = &message["params"];
        let id = message.get("id").cloned();
        let mut out = Vec::new();
        let result = match method.as_str() {
            "initialize" => Some(self.initialize(params)),
            "shutdown" => {
                self.shutdown = true;
                Some(Value::Null)
            }
            "exit" => {
                self.exit = Some(if self.shutdown { 0 } else { 1 });
                None
            }
            "textDocument/didOpen" => {
                let doc = &params["textDocument"];
                let uri = doc["uri"].as_str().unwrap_or("").to_string();
                self.update(&uri, doc["text"].as_str().unwrap_or("").to_string());
                out.push(self.diagnostics(&uri));
                None
            }
            "textDocument/didChange" => {
                let uri = params["textDocument"]["uri"].as_str().unwrap_or("").to_string();
                // Full synchronisation: the last change holds the whole text.
                if let Some(text) = params["contentChanges"].as_array().and_then(|c| c.last()).and_then(|c| c["text"].as_str()) {
                    self.update(&uri, text.to_string());
                    out.push(self.diagnostics(&uri));
                }
                None
            }
            "textDocument/didSave" => {
                // An imported file may have changed underneath this one.
                let uri = params["textDocument"]["uri"].as_str().unwrap_or("").to_string();
                if self.documents.contains_key(&uri) {
                    out.push(self.diagnostics(&uri));
                }
                None
            }
            "textDocument/didClose" => {
                let uri = params["textDocument"]["uri"].as_str().unwrap_or("").to_string();
                self.documents.remove(&uri);
                out.push(notification("textDocument/publishDiagnostics", json!({ "uri": uri, "diagnostics": [] })));
                None
            }
            "textDocument/completion" => Some(self.at(params, Server::completion)),
            "textDocument/hover" => Some(self.at(params, Server::hover)),
            "textDocument/signatureHelp" => Some(self.at(params, Server::signature_help)),
            "textDocument/definition" => Some(self.at(params, Server::definition)),
            "textDocument/formatting" => Some(self.formatting(params)),
            "textDocument/documentSymbol" => Some(self.symbols(params)),
            _ => {
                if let Some(id) = id {
                    out.insert(0, json!({ "jsonrpc": "2.0", "id": id, "error": { "code": -32601, "message": format!("unsupported method {method}") } }));
                }
                return out;
            }
        };
        if let (Some(id), Some(result)) = (id, result) {
            out.insert(0, json!({ "jsonrpc": "2.0", "id": id, "result": result }));
        }
        out
    }

    fn initialize(&mut self, params: &Value) -> Value {
        let offered: Vec<&str> = params["capabilities"]["general"]["positionEncodings"]
            .as_array()
            .map(|a| a.iter().filter_map(Value::as_str).collect())
            .unwrap_or_default();
        self.encoding = if offered.contains(&"utf-32") {
            Encoding::Utf32
        } else if offered.contains(&"utf-8") {
            Encoding::Utf8
        } else {
            Encoding::Utf16
        };
        let encoding = match self.encoding {
            Encoding::Utf8 => "utf-8",
            Encoding::Utf16 => "utf-16",
            Encoding::Utf32 => "utf-32",
        };
        json!({
            "capabilities": {
                "positionEncoding": encoding,
                "textDocumentSync": { "openClose": true, "change": 1, "save": true },
                "completionProvider": { "triggerCharacters": [":", "."] },
                "hoverProvider": true,
                "signatureHelpProvider": { "triggerCharacters": ["(", ",", " "], "retriggerCharacters": [","] },
                "definitionProvider": true,
                "documentFormattingProvider": true,
                "documentSymbolProvider": true,
            },
            "serverInfo": { "name": "hydra", "version": env!("CARGO_PKG_VERSION") },
        })
    }

    fn update(&mut self, uri: &str, text: String) {
        let file = uri_to_path(uri).map(|p| p.display().to_string()).unwrap_or_else(|| uri.to_string());
        let program = parse(&text, &file).ok();
        match self.documents.get_mut(uri) {
            Some(doc) => {
                doc.text = text;
                if program.is_some() {
                    doc.program = program;
                }
            }
            None => {
                self.documents.insert(uri.to_string(), Document { text, program, file });
            }
        }
    }

    /// Run a request at a position in an open document.
    fn at(&self, params: &Value, f: fn(&Server, &Document, &str, Cursor) -> Value) -> Value {
        let uri = params["textDocument"]["uri"].as_str().unwrap_or("");
        let Some(doc) = self.documents.get(uri) else { return Value::Null };
        let line = params["position"]["line"].as_u64().unwrap_or(0) as usize;
        let units = params["position"]["character"].as_u64().unwrap_or(0) as usize;
        let text = doc.line(line);
        let col = self.encoding.to_chars(text, units);
        f(self, doc, uri, Cursor { line, col, chars: text.chars().collect() })
    }

    fn position(&self, doc: &Document, line: usize, col: usize) -> Value {
        json!({ "line": line, "character": self.encoding.to_units(doc.line(line), col) })
    }

    /// The LSP range a Hydra position names: the word starting there.
    fn range_at(&self, doc: &Document, pos: Pos) -> Value {
        if !pos.is_known() {
            return json!({ "start": { "line": 0, "character": 0 }, "end": { "line": 0, "character": 0 } });
        }
        let line = pos.line as usize - 1;
        let col = pos.col as usize - 1;
        let chars: Vec<char> = doc.line(line).chars().collect();
        let mut end = col;
        while end < chars.len() && is_ident_char(chars[end]) {
            end += 1;
        }
        if end == col {
            end = (col + 1).min(chars.len().max(col));
        }
        json!({ "start": self.position(doc, line, col), "end": self.position(doc, line, end) })
    }

    fn diagnostics(&self, uri: &str) -> Value {
        let doc = &self.documents[uri];
        let mut found = Vec::new();
        match parse(&doc.text, &doc.file) {
            Err(e) => found.push(json!({
                "range": self.range_at(doc, e.site.pos),
                "severity": 1,
                "source": "hydra",
                "code": "syntax",
                "message": e.message,
            })),
            Ok(program) => {
                let report = check_program(&program, &CheckOptions::from_env());
                for d in report.sorted() {
                    if d.site.file != doc.file {
                        continue;
                    }
                    found.push(json!({
                        "range": self.range_at(doc, d.site.pos),
                        "severity": if d.severity == Severity::Error { 1 } else { 2 },
                        "source": "hydra check",
                        "code": d.code,
                        "message": d.message,
                    }));
                }
            }
        }
        notification("textDocument/publishDiagnostics", json!({ "uri": uri, "diagnostics": found }))
    }

    fn formatting(&self, params: &Value) -> Value {
        let uri = params["textDocument"]["uri"].as_str().unwrap_or("");
        let Some(doc) = self.documents.get(uri) else { return Value::Null };
        let Ok(formatted) = format_source(&doc.text, &doc.file) else { return Value::Null };
        if formatted == doc.text {
            return json!([]);
        }
        let last = doc.text.split('\n').count() - 1;
        let end = self.position(doc, last, doc.line(last).chars().count());
        json!([{ "range": { "start": { "line": 0, "character": 0 }, "end": end }, "newText": formatted }])
    }

    fn symbols(&self, params: &Value) -> Value {
        let uri = params["textDocument"]["uri"].as_str().unwrap_or("");
        let Some(doc) = self.documents.get(uri) else { return Value::Null };
        let Some(program) = &doc.program else { return json!([]) };
        let mut out = Vec::new();
        for entry in declarations(&program.body, &doc.text, &doc.file, false) {
            let Some((_, start, end)) = &entry.location else { continue };
            let range = json!({ "start": self.range_at(doc, *start)["start"], "end": self.range_at(doc, *end)["end"] });
            out.push(json!({
                "name": entry.name,
                "detail": entry.signatures.first().cloned().unwrap_or_default(),
                "kind": match entry.kind { Kind::Function => 12, Kind::Constant => 14, _ => 13 },
                "range": range,
                "selectionRange": range,
            }));
        }
        Value::Array(out)
    }

    fn completion(&self, doc: &Document, _uri: &str, cursor: Cursor) -> Value {
        let before = &cursor.chars[..cursor.col.min(cursor.chars.len())];
        if mode_at(before) != Mode::Code {
            return json!([]);
        }
        let start = word_start(before);
        let prefix: String = before[start..].iter().collect();
        let head = &before[..start];
        let edit = |label: &str, insert: &str| {
            json!({
                "range": { "start": self.position(doc, cursor.line, start), "end": self.position(doc, cursor.line, cursor.col) },
                "newText": if insert.is_empty() { label } else { insert },
            })
        };
        let item = |entry: &Entry, qualifier: Option<&str>| {
            let mut value = json!({
                "label": entry.name,
                "kind": entry.kind.completion(),
                "textEdit": edit(&entry.name, ""),
            });
            if let Some(detail) = entry.detail(qualifier) {
                value["detail"] = json!(detail);
            }
            let docs = entry.markdown(qualifier);
            if !docs.is_empty() {
                value["documentation"] = json!({ "kind": "markdown", "value": docs });
            }
            value
        };
        let uses = uses(&doc.text);
        let mut items: Vec<Value> = Vec::new();

        // `use ` — a module name.
        let line_head: String = head.iter().collect();
        if line_head.trim_start().strip_prefix("use").is_some_and(|rest| rest.starts_with(char::is_whitespace) && rest.trim().is_empty()) {
            for module in available_modules(&doc.dir()) {
                let summary = REFERENCE["modules"][&module]["summary"].as_str().unwrap_or("Hydra module").to_string();
                items.push(json!({ "label": module, "kind": 9, "detail": summary, "textEdit": edit(&module, "") }));
            }
            return Value::Array(items);
        }

        // `qualifier::` — the names of a module, or the builtins for `::`.
        if head.ends_with(&[':', ':']) {
            let qstart = word_start(&head[..head.len() - 2]);
            let qualifier: String = head[qstart..head.len() - 2].iter().collect();
            let entries = if qualifier.is_empty() {
                natives(None)
            } else {
                self.module_entries(doc, &uses, &qualifier).unwrap_or_default()
            };
            let shown = (!qualifier.is_empty()).then_some(qualifier.as_str());
            return Value::Array(entries.iter().map(|e| item(e, shown)).collect());
        }

        // `:name` — an atom.
        if head.last() == Some(&':') && !head.ends_with(&[':', ':']) {
            let mut seen = HashSet::new();
            for atom in REFERENCE["atoms"].as_array().into_iter().flatten() {
                let name = atom["atom"].as_str().unwrap_or("").trim_start_matches(':').to_string();
                if seen.insert(name.clone()) {
                    items.push(json!({
                        "label": name, "kind": 20, "textEdit": edit(&name, ""),
                        "documentation": { "kind": "markdown", "value": atom["doc"] },
                    }));
                }
            }
            for name in scan(&doc.text).atoms {
                if name != prefix && seen.insert(name.clone()) {
                    items.push(json!({ "label": name, "kind": 20, "textEdit": edit(&name, "") }));
                }
            }
            return Value::Array(items);
        }

        let method = head.last() == Some(&'.');
        let mut seen = HashSet::new();
        // Named arguments of the call the cursor is in.
        if !method {
            if let Some(call) = call_at(before) {
                if call.segment.trim() == prefix {
                    for entry in self.resolve(doc, &uses, call.qualifier.as_deref(), &call.name) {
                        for signature in &entry.signatures {
                            for param in params_of(signature).iter().filter(|p| p.named) {
                                if seen.insert(format!("{}=", param.name)) {
                                    items.push(json!({
                                        "label": format!("{} =", param.name),
                                        "filterText": param.name,
                                        "kind": 5,
                                        "detail": param.text,
                                        "textEdit": edit(&param.name, &format!("{} = ", param.name)),
                                        "sortText": format!("0{}", param.name),
                                    }));
                                }
                            }
                        }
                    }
                }
            }
        }
        let locals = doc.program.as_ref().map(|p| declarations(&p.body, &doc.text, &doc.file, true)).unwrap_or_default();
        for entry in &locals {
            if (!method || entry.kind == Kind::Function) && seen.insert(entry.name.clone()) {
                items.push(item(entry, None));
            }
        }
        for u in &uses {
            if u.star {
                for entry in self.module_entries(doc, &uses, &u.qualifier()).unwrap_or_default() {
                    if (!method || entry.kind == Kind::Function) && seen.insert(entry.name.clone()) {
                        items.push(item(&entry, None));
                    }
                }
            }
        }
        for entry in natives(None) {
            if seen.insert(entry.name.clone()) {
                items.push(item(&entry, None));
            }
        }
        // Qualifiers: `x.list::map(…)` is `list::map(x, …)` (§5.2).
        for u in &uses {
            let qualifier = u.qualifier();
            if seen.insert(qualifier.clone()) {
                let summary = REFERENCE["modules"][&u.module]["summary"].as_str().unwrap_or("Hydra module");
                items.push(json!({ "label": qualifier, "kind": 9, "detail": summary, "textEdit": edit(&qualifier, "") }));
            }
        }
        if method {
            return Value::Array(items);
        }
        let words = scan(&doc.text);
        for word in &words.names {
            if word != &prefix && seen.insert(word.clone()) {
                items.push(json!({ "label": word, "kind": 6, "textEdit": edit(word, "") }));
            }
        }
        for keyword in KEYWORDS.iter().copied().chain(COMPOUND.iter().map(|(_, _, both)| *both)) {
            if seen.insert(keyword.to_string()) {
                items.push(json!({ "label": keyword, "kind": 14, "textEdit": edit(keyword, "") }));
            }
        }
        Value::Array(items)
    }

    fn hover(&self, doc: &Document, _uri: &str, cursor: Cursor) -> Value {
        let chars = &cursor.chars;
        let col = cursor.col.min(chars.len());
        if mode_at(&chars[..col]) != Mode::Code {
            return Value::Null;
        }
        let Some((start, end)) = word_around(chars, col) else { return Value::Null };
        let name: String = chars[start..end].iter().collect();
        let range = json!({ "start": self.position(doc, cursor.line, start), "end": self.position(doc, cursor.line, end) });
        let uses = uses(&doc.text);
        let reply = |markdown: String| json!({ "contents": { "kind": "markdown", "value": markdown }, "range": range });

        // An atom.
        if start > 0 && chars[start - 1] == ':' && (start < 2 || chars[start - 2] != ':') {
            let atom = format!(":{name}");
            return REFERENCE["atoms"]
                .as_array()
                .and_then(|a| a.iter().find(|x| x["atom"] == atom.as_str()))
                .map(|x| reply(format!("`{atom}`\n\n{}", x["doc"].as_str().unwrap_or(""))))
                .unwrap_or(Value::Null);
        }
        // A module qualifier.
        if chars.get(end) == Some(&':') && chars.get(end + 1) == Some(&':') {
            let module = uses.iter().find(|u| u.qualifier() == name).map(|u| u.module.clone()).unwrap_or(name.clone());
            let summary = REFERENCE["modules"][&module]["summary"].as_str().map(str::to_string).or_else(|| {
                resolve_module(&module, &doc.dir()).map(|p| format!("Module `{}`", p.display()))
            });
            return summary.map(|s| reply(format!("```hydra\nuse {module}\n```\n\n{s}"))).unwrap_or(Value::Null);
        }
        let qualifier = qualifier_before(chars, start);
        let entries = self.resolve(doc, &uses, qualifier.as_deref(), &name);
        let Some(entry) = entries.first() else { return Value::Null };
        let shown = qualifier.as_deref().filter(|q| !q.is_empty());
        reply(entry.markdown_full(shown))
    }

    fn signature_help(&self, doc: &Document, _uri: &str, cursor: Cursor) -> Value {
        let before = &cursor.chars[..cursor.col.min(cursor.chars.len())];
        if mode_at(before) != Mode::Code {
            return Value::Null;
        }
        let Some(call) = call_at(before) else { return Value::Null };
        let uses = uses(&doc.text);
        let entries = self.resolve(doc, &uses, call.qualifier.as_deref(), &call.name);
        let Some(entry) = entries.first() else { return Value::Null };
        let shown = call.qualifier.as_deref().filter(|q| !q.is_empty());
        let prefix = shown.map(|q| format!("{q}::")).unwrap_or_default();
        let index = call.commas + usize::from(call.method);
        let named = named_argument(&call.segment);
        let mut signatures = Vec::new();
        let mut active_signature = None;
        let mut active_parameter = 0;
        for signature in &entry.signatures {
            let label = format!("{prefix}{signature}");
            let params = params_of(signature);
            let offset = prefix.encode_utf16().count();
            let parameters: Vec<Value> = params
                .iter()
                .map(|p| json!({ "label": [offset + p.start, offset + p.end] }))
                .collect();
            let active = match &named {
                Some(name) => params.iter().position(|p| p.name == *name),
                None => positional(&params, index),
            };
            if active_signature.is_none() && active.is_some() {
                active_signature = Some(signatures.len());
                active_parameter = active.unwrap_or(0);
            }
            let mut sig = json!({ "label": label, "parameters": parameters });
            if let Some(active) = active {
                sig["activeParameter"] = json!(active);
            } else {
                sig["activeParameter"] = json!(params.len());
            }
            if !entry.doc.is_empty() {
                sig["documentation"] = json!({ "kind": "markdown", "value": entry.doc });
            }
            signatures.push(sig);
        }
        json!({
            "signatures": signatures,
            "activeSignature": active_signature.unwrap_or(0),
            "activeParameter": active_parameter,
        })
    }

    fn definition(&self, doc: &Document, _uri: &str, cursor: Cursor) -> Value {
        let chars = &cursor.chars;
        let col = cursor.col.min(chars.len());
        let Some((start, end)) = word_around(chars, col) else { return Value::Null };
        let name: String = chars[start..end].iter().collect();
        let uses = uses(&doc.text);
        // A qualifier: the module's file.
        if chars.get(end) == Some(&':') && chars.get(end + 1) == Some(&':') {
            let module = uses.iter().find(|u| u.qualifier() == name).map(|u| u.module.clone()).unwrap_or(name);
            return resolve_module(&module, &doc.dir())
                .map(|path| json!({ "uri": path_to_uri(&path), "range": { "start": { "line": 0, "character": 0 }, "end": { "line": 0, "character": 0 } } }))
                .unwrap_or(Value::Null);
        }
        let qualifier = qualifier_before(chars, start);
        let entries = self.resolve(doc, &uses, qualifier.as_deref(), &name);
        // Prefer the last declaration before the cursor, which is the one
        // in reach at the cursor in straight-line code.
        let here = Pos::new(cursor.line as u32 + 1, col as u32 + 1);
        let located: Vec<&Entry> = entries.iter().filter(|e| e.location.is_some()).collect();
        let Some(entry) = located
            .iter()
            .rfind(|e| e.location.as_ref().is_some_and(|(file, start, _)| *file != doc.file || *start <= here))
            .or(located.first())
        else {
            return Value::Null;
        };
        let (file, start, _) = entry.location.as_ref().expect("filtered on location");
        if *file == doc.file {
            return json!({ "uri": _uri, "range": self.range_at(doc, *start) });
        }
        let path = PathBuf::from(file);
        let text = std::fs::read_to_string(&path).unwrap_or_default();
        let target = Document { text, program: None, file: file.clone() };
        json!({ "uri": path_to_uri(&path), "range": self.range_at(&target, *start) })
    }

    /// What `qualifier::name` (or a bare `name`) refers to from `doc`.
    fn resolve(&self, doc: &Document, uses: &[Use], qualifier: Option<&str>, name: &str) -> Vec<Entry> {
        let pick = |entries: Vec<Entry>| entries.into_iter().filter(|e| e.name == name).collect::<Vec<_>>();
        match qualifier {
            Some("") => pick(natives(None)),
            Some(q) => pick(self.module_entries(doc, uses, q).unwrap_or_default()),
            None => {
                let local = doc.program.as_ref().map(|p| pick(declarations(&p.body, &doc.text, &doc.file, true))).unwrap_or_default();
                if !local.is_empty() {
                    return local;
                }
                for u in uses.iter().filter(|u| u.star) {
                    let found = pick(self.module_entries(doc, uses, &u.qualifier()).unwrap_or_default());
                    if !found.is_empty() {
                        return found;
                    }
                }
                pick(natives(None))
            }
        }
    }

    /// The exported names of the module `qualifier` names in `doc`.
    fn module_entries(&self, doc: &Document, uses: &[Use], qualifier: &str) -> Option<Vec<Entry>> {
        let module = uses.iter().find(|u| u.qualifier() == qualifier).map(|u| u.module.as_str()).unwrap_or(qualifier);
        // A file shadows a standard module of the same name (§7).
        if let Some(path) = resolve_module(module, &doc.dir()) {
            let file = path.display().to_string();
            let text = std::fs::read_to_string(&path).ok()?;
            let program = parse(&text, &file).ok()?;
            let entries = declarations(&program.body, &text, &file, false);
            return Some(entries.into_iter().filter(|e| !is_private(&e.name)).collect());
        }
        BUILTIN_MODULES.contains(&module).then(|| natives(Some(module)))
    }
}

fn notification(method: &str, params: Value) -> Value {
    json!({ "jsonrpc": "2.0", "method": method, "params": params })
}

struct Cursor {
    line: usize,
    col: usize,
    chars: Vec<char>,
}

#[derive(Clone, Copy, Debug, PartialEq)]
enum Kind {
    Function,
    Variable,
    Constant,
}

impl Kind {
    fn completion(self) -> u32 {
        match self {
            Kind::Function => 3,
            Kind::Variable => 6,
            Kind::Constant => 21,
        }
    }
}

/// Something a name can complete to.
#[derive(Clone, Debug)]
struct Entry {
    name: String,
    kind: Kind,
    /// `read(path)`, without a qualifier; one per overload.
    signatures: Vec<String>,
    result: Option<String>,
    doc: String,
    /// The file, the declaration, and where it ends.
    location: Option<(String, Pos, Pos)>,
}

impl Entry {
    fn detail(&self, qualifier: Option<&str>) -> Option<String> {
        let prefix = qualifier.map(|q| format!("{q}::")).unwrap_or_default();
        let first = self.signatures.first()?;
        let more = match self.signatures.len() {
            1 => String::new(),
            n => format!(" (+{} overload{})", n - 1, if n == 2 { "" } else { "s" }),
        };
        let result = self.result.as_ref().map(|r| format!(" → {r}")).unwrap_or_default();
        Some(format!("{prefix}{first}{result}{more}"))
    }

    fn markdown(&self, qualifier: Option<&str>) -> String {
        let prefix = qualifier.map(|q| format!("{q}::")).unwrap_or_default();
        let mut out = String::new();
        if self.signatures.len() > 1 {
            out.push_str("```hydra\n");
            for signature in &self.signatures {
                out.push_str(&format!("{prefix}{signature}\n"));
            }
            out.push_str("```\n\n");
        }
        out.push_str(&self.doc);
        out
    }

    fn markdown_full(&self, qualifier: Option<&str>) -> String {
        let prefix = qualifier.map(|q| format!("{q}::")).unwrap_or_default();
        let mut out = String::from("```hydra\n");
        if self.signatures.is_empty() {
            out.push_str(&format!("{prefix}{}\n", self.name));
        }
        for signature in &self.signatures {
            out.push_str(&format!("{prefix}{signature}\n"));
        }
        out.push_str("```\n");
        if let Some(result) = &self.result {
            out.push_str(&format!("\n→ `{result}`\n"));
        }
        if !self.doc.is_empty() {
            out.push_str(&format!("\n{}", self.doc));
        }
        out
    }
}

/// The builtins (`None`) or a standard module's functions, overloads grouped.
fn natives(module: Option<&str>) -> Vec<Entry> {
    let mut out: Vec<Entry> = Vec::new();
    for native in NATIVES {
        let info = native.info();
        if info.module != module {
            continue;
        }
        if let Some(entry) = out.iter_mut().find(|e| e.name == info.name) {
            entry.signatures.push(info.signature.to_string());
            continue;
        }
        let described = match module {
            None => &REFERENCE["builtins"][info.name],
            Some(m) => &REFERENCE["modules"][m]["functions"][info.name],
        };
        out.push(Entry {
            name: info.name.to_string(),
            kind: Kind::Function,
            signatures: vec![info.signature.to_string()],
            result: described["result"].as_str().map(str::to_string),
            doc: described["doc"].as_str().unwrap_or("").to_string(),
            location: None,
        });
    }
    out
}

/// The functions and variables a program declares. `nested` includes those
/// inside blocks and function bodies as well as the toplevel ones.
fn declarations(body: &[Stmt], src: &str, file: &str, nested: bool) -> Vec<Entry> {
    let lines: Vec<&str> = src.split('\n').collect();
    let comments = comment_lines(src);
    let mut out = Vec::new();
    collect(body, &lines, &comments, file, nested, &mut out);
    out
}

fn collect(body: &[Stmt], lines: &[&str], comments: &HashMap<usize, String>, file: &str, nested: bool, out: &mut Vec<Entry>) {
    let function = |name: &str, pos: Pos, end: Pos| Entry {
        name: name.to_string(),
        kind: Kind::Function,
        signatures: signature_at(lines, pos, name).into_iter().collect(),
        result: None,
        doc: doc_comment(comments, pos),
        location: Some((file.to_string(), pos, end)),
    };
    for stmt in body {
        match stmt {
            Stmt::FnDecl { name, def, pos } => {
                out.push(function(name, *pos, def.end_pos));
                if nested {
                    if let ClosureBody::Block(b) = &def.body {
                        collect(b, lines, comments, file, nested, out);
                    }
                }
            }
            Stmt::Decl { names, value, pos } => {
                if let (Expr::Closure(def), [name]) = (value, names.as_slice()) {
                    out.push(function(name, *pos, def.end_pos));
                    continue;
                }
                for name in names.iter().filter(|n| *n != "_") {
                    let constant = name.chars().any(|c| c.is_ascii_uppercase()) && !name.chars().any(|c| c.is_ascii_lowercase());
                    out.push(Entry {
                        name: name.clone(),
                        kind: if constant { Kind::Constant } else { Kind::Variable },
                        signatures: Vec::new(),
                        result: None,
                        doc: doc_comment(comments, *pos),
                        location: Some((file.to_string(), *pos, *pos)),
                    });
                }
            }
            Stmt::If { branches, .. } if nested => {
                for branch in branches {
                    collect(&branch.body, lines, comments, file, nested, out);
                }
            }
            Stmt::For { body, .. } | Stmt::While { body, .. } | Stmt::ParallelFor { body, .. } | Stmt::ParallelWhile { body, .. } if nested => {
                collect(body, lines, comments, file, nested, out);
            }
            Stmt::Parallel { trails, .. } if nested => {
                for trail in trails {
                    collect(&trail.body, lines, comments, file, nested, out);
                }
            }
            _ => {}
        }
    }
}

/// Whole-line `//` comments by zero-based line, without the slashes.
fn comment_lines(src: &str) -> HashMap<usize, String> {
    src.split('\n')
        .enumerate()
        .filter_map(|(i, line)| {
            let text = line.trim().strip_prefix("//")?;
            Some((i, text.strip_prefix(' ').unwrap_or(text).trim_end().to_string()))
        })
        .collect()
}

/// The comment block directly above a declaration.
fn doc_comment(comments: &HashMap<usize, String>, pos: Pos) -> String {
    let mut lines = Vec::new();
    let mut line = pos.line as usize;
    while line >= 2 {
        match comments.get(&(line - 2)) {
            Some(text) => lines.push(text.as_str()),
            None => break,
        }
        line -= 1;
    }
    lines.reverse();
    lines.join("\n")
}

/// `name(params)` as written at a `fn` declaration, whitespace collapsed.
fn signature_at(lines: &[&str], pos: Pos, name: &str) -> Option<String> {
    let first = pos.line.checked_sub(1)? as usize;
    let text: String = lines.get(first..)?.join("\n");
    let skip: usize = text.chars().take(pos.col.saturating_sub(1) as usize).map(char::len_utf8).sum();
    let text = &text[skip.min(text.len())..];
    let at = text.find("fn")?;
    let open = at + text[at..].find('(')?;
    let mut depth = 0;
    let mut in_string = false;
    let mut close = None;
    for (i, c) in text[open..].char_indices() {
        match c {
            '"' => in_string = !in_string,
            '(' | '[' | '{' if !in_string => depth += 1,
            ')' | ']' | '}' if !in_string => {
                depth -= 1;
                if depth == 0 {
                    close = Some(open + i);
                    break;
                }
            }
            _ => {}
        }
    }
    let params = &text[open + 1..close?];
    let params = params.split_whitespace().collect::<Vec<_>>().join(" ");
    let params = params.replace("( ", "(").replace(" )", ")");
    Some(format!("{name}({})", params.trim_end_matches(',').trim()))
}

/// One parameter of a signature string, with its UTF-16 offsets in it.
struct Param {
    name: String,
    text: String,
    start: usize,
    end: usize,
    /// Only fillable by name: it has a default or follows `*`.
    named: bool,
    variadic: bool,
    /// The bare `*`, which takes no argument.
    marker: bool,
}

fn params_of(signature: &str) -> Vec<Param> {
    let Some(open) = signature.find('(') else { return Vec::new() };
    let Some(close) = signature.rfind(')') else { return Vec::new() };
    let mut out = Vec::new();
    let mut depth = 0;
    let mut in_string = false;
    let mut piece_start = open + 1;
    let mut keyword_only = false;
    let mut finish = |from: usize, to: usize, keyword_only: &mut bool| {
        let raw = &signature[from..to];
        let text = raw.trim();
        if text.is_empty() {
            return;
        }
        let lead = raw.len() - raw.trim_start().len();
        let start = signature[..from + lead].encode_utf16().count();
        let end = start + text.encode_utf16().count();
        let marker = text == "*";
        let variadic = !marker && text.trim_end_matches(char::is_whitespace).ends_with('*');
        let name: String = text.trim_start_matches('&').chars().take_while(|c| is_ident_char(*c)).collect();
        let named = *keyword_only || text.contains('=');
        if marker || variadic {
            *keyword_only = true;
        }
        out.push(Param { name, text: text.to_string(), start, end, named, variadic, marker });
    };
    for (i, c) in signature[open + 1..close].char_indices() {
        let i = open + 1 + i;
        match c {
            '"' => in_string = !in_string,
            '(' | '[' | '{' if !in_string => depth += 1,
            ')' | ']' | '}' if !in_string => depth -= 1,
            ',' if !in_string && depth == 0 => {
                finish(piece_start, i, &mut keyword_only);
                piece_start = i + 1;
            }
            _ => {}
        }
    }
    finish(piece_start, close, &mut keyword_only);
    out
}

/// The parameter the `index`th positional argument fills.
fn positional(params: &[Param], index: usize) -> Option<usize> {
    for (i, param) in params.iter().enumerate() {
        if param.marker {
            return None;
        }
        if param.variadic || i == index {
            return Some(i);
        }
    }
    None
}

/// `name = …` at the start of an argument: the parameter it names.
fn named_argument(segment: &str) -> Option<String> {
    let segment = segment.trim_start();
    let name: String = segment.chars().take_while(|c| is_ident_char(*c)).collect();
    if name.is_empty() || !name.starts_with(is_ident_start) {
        return None;
    }
    let rest = segment[name.len()..].trim_start();
    (rest.starts_with('=') && !rest.starts_with("==")).then_some(name)
}

#[derive(Clone, Copy, Debug, PartialEq)]
enum Mode {
    Code,
    Str,
    Comment,
}

/// Whether the end of `chars` (one line) is in code, a string or a comment.
/// Code inside an interpolation `\(…)` counts as code.
fn mode_at(chars: &[char]) -> Mode {
    mask(chars).1
}

/// `chars` with string contents and comments blanked out, so that a comma or
/// a parenthesis inside them is not mistaken for code, and the mode at the end.
fn mask(chars: &[char]) -> (Vec<char>, Mode) {
    // Each entry is a string, or an interpolation's paren depth.
    let mut stack: Vec<Option<u32>> = Vec::new();
    let mut out = Vec::with_capacity(chars.len());
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match stack.last().copied() {
            Some(None) => {
                if c == '\\' && chars.get(i + 1) == Some(&'(') {
                    stack.push(Some(0));
                    out.extend(['\u{1}', '\u{1}']);
                    i += 2;
                    continue;
                }
                if c == '\\' {
                    out.extend(['\u{1}', '\u{1}']);
                    i += 2;
                    continue;
                }
                if c == '"' {
                    stack.pop();
                }
                out.push('\u{1}');
            }
            depth => {
                if c == '/' && chars.get(i + 1) == Some(&'/') {
                    out.extend(std::iter::repeat_n('\u{1}', chars.len() - i));
                    out.truncate(chars.len());
                    return (out, Mode::Comment);
                }
                match c {
                    '"' => {
                        stack.push(None);
                        out.push('\u{1}');
                    }
                    '(' if let Some(Some(d)) = depth => {
                        *stack.last_mut().expect("in an interpolation") = Some(d + 1);
                        out.push(c);
                    }
                    ')' if depth == Some(Some(0)) => {
                        stack.pop();
                        out.push('\u{1}');
                    }
                    ')' if let Some(Some(d)) = depth => {
                        *stack.last_mut().expect("in an interpolation") = Some(d - 1);
                        out.push(c);
                    }
                    _ => out.push(c),
                }
            }
        }
        i += 1;
    }
    out.truncate(chars.len());
    let mode = match stack.last() {
        Some(None) => Mode::Str,
        _ => Mode::Code,
    };
    (out, mode)
}

fn word_start(chars: &[char]) -> usize {
    let mut start = chars.len();
    while start > 0 && is_ident_char(chars[start - 1]) {
        start -= 1;
    }
    start
}

fn word_around(chars: &[char], col: usize) -> Option<(usize, usize)> {
    let mut start = col.min(chars.len());
    while start > 0 && is_ident_char(chars[start - 1]) {
        start -= 1;
    }
    let mut end = col.min(chars.len());
    while end < chars.len() && is_ident_char(chars[end]) {
        end += 1;
    }
    (start < end && is_ident_start(chars[start])).then_some((start, end))
}

/// `Some("fs")` for a name written `fs::name`, `Some("")` for `::name`.
fn qualifier_before(chars: &[char], start: usize) -> Option<String> {
    if start < 2 || chars[start - 1] != ':' || chars[start - 2] != ':' {
        return None;
    }
    let end = start - 2;
    let qstart = word_start(&chars[..end]);
    Some(chars[qstart..end].iter().collect())
}

/// The call whose arguments the end of `before` is in.
#[derive(Debug)]
struct Call {
    qualifier: Option<String>,
    name: String,
    /// Arguments before the current one.
    commas: usize,
    /// `x.f(…)`: `x` is the first argument.
    method: bool,
    /// The text of the argument being written.
    segment: String,
}

fn call_at(before: &[char]) -> Option<Call> {
    let (masked, _) = mask(before);
    let mut depth = 0;
    let mut i = masked.len();
    while i > 0 {
        i -= 1;
        match masked[i] {
            ')' | ']' | '}' => depth += 1,
            '[' | '{' if depth == 0 => return None,
            '(' if depth == 0 => {
                let end = i;
                let start = word_start(&masked[..end]);
                if start == end {
                    // A grouping parenthesis: the call, if any, is outside it.
                    continue;
                }
                return call_from(before, &masked, start, end, i + 1);
            }
            '(' | '[' | '{' => depth -= 1,
            _ => {}
        }
    }
    // A call without parentheses: `print x, y` or `a := f x`.
    let text: String = masked.iter().collect();
    let lead = text.len() - text.trim_start().len();
    let mut from = lead;
    if let Some(at) = assignment(&masked) {
        from = at;
        while from < masked.len() && masked[from].is_whitespace() {
            from += 1;
        }
    }
    let mut end = from;
    while end < masked.len() && (is_ident_char(masked[end]) || (masked[end] == ':' && masked.get(end + 1) == Some(&':')) || (end > from && masked[end - 1] == ':' && masked[end] == ':')) {
        end += 1;
    }
    if end == from || end >= masked.len() || !masked[end].is_whitespace() {
        return None;
    }
    let name_start = word_start(&masked[..end]);
    let word: String = masked[name_start..end].iter().collect();
    if KEYWORDS.contains(&word.as_str()) || !word.starts_with(is_ident_start) {
        return None;
    }
    let rest: String = masked[end..].iter().collect();
    let first = rest.trim_start().chars().next();
    // `f - 1` and `f == x` are not calls.
    if let Some(c) = first {
        let spaced_op = "=+*/%<>|^!.".contains(c) || (c == '-' && rest.trim_start().chars().nth(1).is_none_or(char::is_whitespace));
        if spaced_op || rest.trim_start().starts_with("and ") || rest.trim_start().starts_with("or ") || rest.trim_start().starts_with("in ") {
            return None;
        }
    }
    call_from(before, &masked, name_start, end, end)
}

/// Where the right-hand side of a toplevel `:=` or `=` starts.
fn assignment(masked: &[char]) -> Option<usize> {
    let mut depth = 0;
    for i in 0..masked.len() {
        match masked[i] {
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth -= 1,
            '=' if depth == 0 => {
                let prev = i.checked_sub(1).map(|j| masked[j]);
                let next = masked.get(i + 1).copied();
                if next == Some('=') || matches!(prev, Some('=' | '!' | '<' | '>')) {
                    continue;
                }
                // `print x, stream = …` names an argument; it assigns
                // nothing.
                return targets(&masked[..i]).then_some(i + 1);
            }
            _ => {}
        }
    }
    None
}

/// Whether `text` (before a `=`) is a list of places: `a`, `a.b, c[0]`,
/// `x +` for a compound assignment.
fn targets(text: &[char]) -> bool {
    let text: String = text.iter().collect();
    let text = text.trim_end().trim_end_matches(|c| ":+-*/%|&^<>".contains(c)).trim_end();
    let mut depth = 0;
    let mut any = false;
    for part in text.split(',') {
        let part = part.trim();
        if part.is_empty() || !part.starts_with(is_ident_start) {
            return false;
        }
        for c in part.chars() {
            match c {
                '[' | '(' => depth += 1,
                ']' | ')' => depth -= 1,
                c if depth == 0 && !(is_ident_char(c) || c == '.' || c == ':') => return false,
                _ => {}
            }
        }
        any = true;
    }
    any
}

fn call_from(before: &[char], masked: &[char], start: usize, end: usize, args: usize) -> Option<Call> {
    let name: String = masked[start..end].iter().collect();
    if !name.starts_with(is_ident_start) || KEYWORDS.contains(&name.as_str()) {
        return None;
    }
    let qualifier = qualifier_before(masked, start);
    let head = match &qualifier {
        Some(q) => start - 2 - q.chars().count(),
        None => start,
    };
    let method = head > 0 && masked[head - 1] == '.';
    let mut depth = 0;
    let mut commas = 0;
    let mut segment_start = args;
    for (i, c) in masked.iter().enumerate().skip(args) {
        match c {
            '(' | '[' | '{' => depth += 1,
            ')' | ']' | '}' => depth -= 1,
            ',' if depth == 0 => {
                commas += 1;
                segment_start = i + 1;
            }
            _ => {}
        }
    }
    Some(Call { qualifier, name, commas, method, segment: before[segment_start..].iter().collect() })
}

/// A `use` line.
#[derive(Debug)]
struct Use {
    module: String,
    alias: Option<String>,
    star: bool,
}

impl Use {
    /// The name the module is qualified with.
    fn qualifier(&self) -> String {
        self.alias.clone().unwrap_or_else(|| self.module.clone())
    }
}

/// Every `use` in a document, read from its lines so that a document that
/// does not parse still knows its imports.
fn uses(text: &str) -> Vec<Use> {
    let mut out = Vec::new();
    for line in text.lines() {
        let line = line.split("//").next().unwrap_or("");
        let mut words = line.split_whitespace();
        if words.next() != Some("use") {
            continue;
        }
        let Some(module) = words.next().filter(|m| m.chars().all(is_ident_char)) else { continue };
        let (alias, star) = match (words.next(), words.next()) {
            (Some("as"), Some("*")) => (None, true),
            (Some("as"), Some(alias)) => (Some(alias.to_string()), false),
            _ => (None, false),
        };
        out.push(Use { module: module.to_string(), alias, star });
    }
    out
}

fn search_path() -> Vec<PathBuf> {
    std::env::var("HYDRA_PATH")
        .map(|v| v.split(':').filter(|s| !s.is_empty()).map(PathBuf::from).collect())
        .unwrap_or_default()
}

/// The file `use name` loads from `dir`, as the interpreter looks for it (§7).
fn resolve_module(name: &str, dir: &Path) -> Option<PathBuf> {
    let filename = format!("{name}.hy");
    std::iter::once(dir.to_path_buf()).chain(search_path()).map(|d| d.join(&filename)).find(|p| p.is_file())
}

/// Standard modules, then the `.hy` files a `use` could load.
fn available_modules(dir: &Path) -> Vec<String> {
    let mut out: Vec<String> = BUILTIN_MODULES.iter().map(|m| m.to_string()).collect();
    for d in std::iter::once(dir.to_path_buf()).chain(search_path()) {
        let Ok(entries) = std::fs::read_dir(&d) else { continue };
        let mut names: Vec<String> = entries
            .filter_map(|e| e.ok())
            .filter_map(|e| e.file_name().to_str()?.strip_suffix(".hy").map(str::to_string))
            .filter(|n| crate::lexer::is_identifier(n))
            .collect();
        names.sort();
        for name in names {
            if !out.contains(&name) {
                out.push(name);
            }
        }
    }
    out
}

/// Names and atoms written anywhere in a document, for completing what the
/// tree does not know about: parameters, loop variables, and whatever is in
/// the lines that do not parse yet.
#[derive(Default)]
struct Words {
    names: Vec<String>,
    atoms: Vec<String>,
}

fn scan(text: &str) -> Words {
    let mut words = Words::default();
    let mut seen = HashSet::new();
    for line in text.lines() {
        let chars: Vec<char> = line.chars().collect();
        let (masked, _) = mask(&chars);
        let mut i = 0;
        while i < masked.len() {
            if !is_ident_start(masked[i]) || (i > 0 && is_ident_char(masked[i - 1])) {
                i += 1;
                continue;
            }
            let start = i;
            while i < masked.len() && is_ident_char(masked[i]) {
                i += 1;
            }
            let word: String = masked[start..i].iter().collect();
            let prev = start.checked_sub(1).map(|j| masked[j]);
            let qualified = start >= 2 && masked[start - 2] == ':' && prev == Some(':');
            let module = masked.get(i) == Some(&':') && masked.get(i + 1) == Some(&':');
            if prev == Some(':') && !qualified {
                if seen.insert(format!(":{word}")) {
                    words.atoms.push(word);
                }
            } else if prev != Some('.') && !qualified && !module && !KEYWORDS.contains(&word.as_str()) && seen.insert(word.clone()) {
                words.names.push(word);
            }
        }
    }
    words
}

fn uri_to_path(uri: &str) -> Option<PathBuf> {
    let rest = uri.strip_prefix("file://")?;
    let bytes = rest.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            if let Ok(byte) = u8::from_str_radix(std::str::from_utf8(&bytes[i + 1..i + 3]).ok()?, 16) {
                out.push(byte);
                i += 3;
                continue;
            }
        }
        out.push(bytes[i]);
        i += 1;
    }
    Some(PathBuf::from(String::from_utf8(out).ok()?))
}

fn path_to_uri(path: &Path) -> String {
    let path = std::fs::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
    let mut out = String::from("file://");
    for byte in path.display().to_string().bytes() {
        if byte.is_ascii_alphanumeric() || b"/-_.~".contains(&byte) {
            out.push(byte as char);
        } else {
            out.push_str(&format!("%{byte:02X}"));
        }
    }
    out
}
